import { guardPannellum, sanitizeHTML } from '../../../../utils/sanitize';
import { useEffect, useRef } from "react";
import { panoDown, panoLeft, panoRight, panoUp } from "../../utils/icons";
import { toast, ToastContainer } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import useGutenbergDragFix from "../../../../hooks/useGutenbergDragFix";

const ImageViewer = ({ attributes, setAttributes, isButton = true, isBackend = false, isSelected = false }) => {
  const { imageUrl, panoramaFormat = "equirectangular", haov = 360, vaov = 180, vOffset = 0, cubeMap = {}, previewImgUrl = "", loadButtonText = "Click to Load Panorama", options, customControl } = attributes || {};

  const {
    autoLoad,
    hideDefaultCtrl,
    initialViewPosition,
    draggable,
    mouseZoom,
    initialView,
    disableKeyboardCtrl,
    doubleClickZoom,
    isRotate,
    autoRotateSpeed,
    compass,
    orientation = false,
    autoRotateInactivityDelay,
    titleAuthor,
    title,
    author,
    isByline,
  } = options || {};

  const { pitch, yaw, hfov } = initialViewPosition || {};

  const panoramaRef = useRef(null);
  const viewerInstance = useRef(null);
  const buttonRef = useRef(null);
  const controlsRef = useRef(null);

  useGutenbergDragFix(panoramaRef, panoramaRef, isBackend, isSelected);

  useEffect(() => {
    const { pannellum } = window || {};

    if (pannellum && panoramaRef.current) {
      const isCubemap = panoramaFormat === "cubemap";
      const isAllFacesUploaded = Boolean(
        cubeMap?.front &&
        cubeMap?.right &&
        cubeMap?.back &&
        cubeMap?.left &&
        cubeMap?.up &&
        cubeMap?.down
      );

      if (isCubemap && !isAllFacesUploaded) {
        return;
      }
      if (!isCubemap && !imageUrl) {
        return;
      }

      const config = {
        preview: previewImgUrl,
        autoLoad,
        showZoomCtrl: !hideDefaultCtrl,
        draggable,
        mouseZoom,
        showFullscreenCtrl: !hideDefaultCtrl,
        pitch,
        yaw,
        hfov,
        disableKeyboardCtrl,
        doubleClickZoom,
        autoRotate: isRotate ? autoRotateSpeed : 0,
        compass,
        orientationOnByDefault: !isBackend && Boolean(orientation),
        autoRotateInactivityDelay,
        title: titleAuthor ? title : "",
        author: titleAuthor && author ? author : "",
        strings: {
          bylineLabel: (titleAuthor && author) ? (isByline ? `by ${author}` : author) : "",
        }
      };

      if (isCubemap && isAllFacesUploaded) {
        config.type = "cubemap";
        config.cubeMap = [
          cubeMap.front,
          cubeMap.right,
          cubeMap.back,
          cubeMap.left,
          cubeMap.up,
          cubeMap.down
        ];
      } else if (panoramaFormat === "cylindrical") {
        const currentHaov = parseFloat(haov);
        const currentVaov = parseFloat(vaov);
        const currentVOffset = parseFloat(vOffset);
        config.type = "equirectangular";
        config.panorama = imageUrl;
        config.haov = currentHaov;
        config.vaov = currentVaov;
        config.vOffset = currentVOffset;
        if (currentVaov < 180) {
          config.maxPitch = currentVaov / 2;
          config.minPitch = -currentVaov / 2;
        }
        if (currentHaov < 360) {
          config.maxYaw = currentHaov / 2;
          config.minYaw = -currentHaov / 2;
        }
      } else {
        config.type = "equirectangular";
        config.panorama = imageUrl;
      }

      viewerInstance.current = guardPannellum().viewer(panoramaRef.current, config);

      if (!autoLoad) {
        setTimeout(() => {
          const loadBtn = panoramaRef.current?.querySelector(".pnlm-load-button p");
          if (loadBtn) loadBtn.innerHTML = sanitizeHTML(String(loadButtonText || "").replace(/\n/g, "<br>"));
        }, 120);
      }


      if (!titleAuthor || (!title && !author)) {
        setTimeout(() => {
          const infoBox = panoramaRef.current?.querySelector(".pnlm-panorama-info");
          if (infoBox) infoBox.remove();
        }, 50);
      }

      if (buttonRef.current && panoramaRef.current) {
        panoramaRef.current.appendChild(buttonRef.current);
      }

      // Add custom control event listeners if controlsRef exists
      const controlListeners = [];
      if (controlsRef.current) {
        const panUp = controlsRef.current.querySelector(".pan-up");
        const panDown = controlsRef.current.querySelector(".pan-down");
        const panLeft = controlsRef.current.querySelector(".pan-left");
        const panRight = controlsRef.current.querySelector(".pan-right");

        const onPanUp = () => {
          if (viewerInstance.current) {
            viewerInstance.current.setPitch(viewerInstance.current.getPitch() + 10);
          }
        };
        const onPanDown = () => {
          if (viewerInstance.current) {
            viewerInstance.current.setPitch(viewerInstance.current.getPitch() - 10);
          }
        };
        const onPanLeft = () => {
          if (viewerInstance.current) {
            viewerInstance.current.setYaw(viewerInstance.current.getYaw() - 10);
          }
        };
        const onPanRight = () => {
          if (viewerInstance.current) {
            viewerInstance.current.setYaw(viewerInstance.current.getYaw() + 10);
          }
        };

        if (panUp) {
          panUp.addEventListener("click", onPanUp);
          controlListeners.push({ el: panUp, handler: onPanUp });
        }
        if (panDown) {
          panDown.addEventListener("click", onPanDown);
          controlListeners.push({ el: panDown, handler: onPanDown });
        }
        if (panLeft) {
          panLeft.addEventListener("click", onPanLeft);
          controlListeners.push({ el: panLeft, handler: onPanLeft });
        }
        if (panRight) {
          panRight.addEventListener("click", onPanRight);
          controlListeners.push({ el: panRight, handler: onPanRight });
        }
      }

      return () => {
        // Destroy Pannellum viewer
        if (viewerInstance.current) {
          viewerInstance.current.destroy();
        }

        // Clean up control listeners
        controlListeners.forEach(({ el, handler }) => {
          el.removeEventListener("click", handler);
        });
      };
    }
  }, [
    imageUrl,
    panoramaFormat,
    haov,
    vaov,
    vOffset,
    JSON.stringify(cubeMap),
    previewImgUrl,
    loadButtonText,
    autoLoad,
    hideDefaultCtrl,
    draggable,
    mouseZoom,
    initialView,
    initialViewPosition,
    disableKeyboardCtrl,
    doubleClickZoom,
    isRotate,
    autoRotateSpeed,
    compass,
    orientation,
    autoRotateInactivityDelay,
    titleAuthor,
    title,
    author,
    customControl,
    isByline
  ]);


  const handleSetInitialView = () => {
    try {
      if (viewerInstance.current) {
        setAttributes({
          options: {
            ...options,
            initialViewPosition: {
              pitch: viewerInstance.current.getPitch(),
              yaw: viewerInstance.current.getYaw(),
              hfov: viewerInstance.current.getHfov(),
            },
          },
        });
        toast.success("Initial view set successfully", { position: "bottom-center" });
      } else {
        toast.error("VR view not initialized!", { position: "top-right" });
      }
    } catch (error) {
      console.error(error);
      toast.error("Failed to set initial view ⚠️", { position: "top-right" });
    }
  };

  return (
    <>
      <ToastContainer />

      <div
        key={`${panoramaFormat}-${JSON.stringify(cubeMap)}-${autoLoad}-${title}-${author}-${isByline}-${titleAuthor}-${loadButtonText}-${hideDefaultCtrl}-${compass}-${doubleClickZoom}`}
        ref={panoramaRef}
        className="panoramaImgViewer"
      >
        {isButton && initialView && (
          <button
            ref={buttonRef}
            onClick={handleSetInitialView}
            className="setInitialViewButton"
          >
            Set as Initial View
          </button>
        )}
        {customControl && (
          <div id="controls" ref={controlsRef}>
            <div className="ctrl pan-left">{panoUp}</div>
            <div className="ctrl pan-right">{panoDown}</div>
            <div className="ctrl pan-up">{panoLeft}</div>
            <div className="ctrl pan-down">{panoRight}</div>
          </div>
        )}
      </div>

    </>
  );
};

export default ImageViewer;